import React from 'react';
import Header from './Header';
import BottomNavigation from '../components/BottomNavigation';
import { useAuthStore } from '../store/authStore';
import { useThemeStore } from '../store/themeStore';

export default function Layout({ children }: { children: React.ReactNode }) {
  const { displayName } = useAuthStore();
  const { isDarkMode } = useThemeStore();
  return (
    <div className={`min-h-screen flex flex-col ${isDarkMode ? 'bg-gray-900' : 'bg-gray-50'}`}>
      <Header userName={displayName} />
      <div className="flex-1 flex flex-col" style={{ minHeight: '100vh' }}>
        <main
          className="flex-1 max-w-7xl mx-auto w-full px-4 md:px-4 pb-20 md:pb-10 overflow-y-auto pt-2"
          style={{
            paddingTop: 80, // altura do header mobile (maior para acomodar título + saudação)
            paddingBottom: 80, // espaço para bottom navigation em mobile
            height: 'calc(100vh - 80px)',
          }}
        >
          <style>{`
            @media (min-width: 768px) {
              main {
                padding-top: 64px !important;
                padding-bottom: 20px !important;
                height: calc(100vh - 64px) !important;
              }
            }
          `}</style>
          {children}
        </main>
      </div>
      <BottomNavigation />
      <style>{`
        header { position: fixed; top: 0; left: 0; right: 0; z-index: 50; }
      `}</style>
    </div>
  );
} 